             if (
               (methodName === 'created' ||
                 methodName === 'mounted' ||
                 methodName === 'beforeUpdate' ||
                 methodName === 'updated') &&
               context.getAncestors().some(
                 parent =>
                   parent.type === 'MethodDefinition' &&
