```javascript
function getRandomThunderSoundDescription() {
  const adjectives = ["bruyant", "explosif", "rumble", "ionisant", "moralement secouant", "grondant", "tonitruant", "grondant comme une forteresse", "foudroyant", "soulignant"];
  const adverbs = ["violentement", "soudainement", "profondément", "explosivement", "étonnamment", "assourdissant"];
  const nouns = ["tonnerre", "appel", "éclair", "raglement de bottes", "retour de foudre", "explosion", "crachat de Zeus"];

  const randomIndex = Math.floor(Math.random() * (adjectives.length + adverbs.length + nouns.length));
  let description = "";

  if (randomIndex < adjectives.length) {
    description += adjectives[randomIndex];
  } else if (randomIndex >= adjectives.length && randomIndex < (adjectives.length + adverbs.length)) {
    randomIndex -= adjectives.length;
    description += adverbs[randomIndex];
  } else {
    randomIndex -= (adjectives.length + adverbs.length);
    description += nouns[randomIndex];
  }

  if (description.endsWith("ing") && Math.random() < 0.5) {
    description += "s";
  }

  return description;
}
```

