// Définissez les constantes pour le nombre de questions et le nombre de points par bonnes réponses.
const NUM_QUESTIONS = 10;
const POINTS_PER_QUESTION = 1;

// Génère un nombre aléatoire entre min (inclusive) et max (exclusive).
function getRandomNumber(min, max) {
  return Math.floor(Math.random() * (max - min)) + min;
}

// Génère une énigme simple arithmétique (addition ou soustraction).
function generateSimpleMathPuzzle() {
  const operators = ['+', '-'];
  const num1 = getRandomNumber(1, 20); // Choisissez les nombres entre 1 et 20 pour simplifier le jeu.
  const operatorIndex = Math.floor(Math.random() * operators.length);
  let num2, result;
  if (operatorIndex === 0) {
    num2 = getRandomNumber(1, 20);
    result = num1 + num2;
  } else {
    num2 = getRandomNumber(1, num1); // Pour la soustraction, assurez-vous que le second nombre est inférieur ou égal au premier.
    result = num1 - num2;
  }
  return { num1, num2, operators[operatorIndex], result };
}

// Fonction pour vérifier la réponse.
function checkAnswer(puzzle, answer) {
  return puzzle.result === answer;
}

// Fonction pour générer le prochain puzzle, ajouter à la liste des statistiques, et afficher la question.
function nextQuestion() {
  const puzzle = generateSimpleMathPuzzle();
  const oldScore = document.getElementById('score').textContent; // Stocker le score actuel.
  const question = `${puzzle.num1} ${puzzle.operators} ${puzzle.num2} =`;

  // Mettre à jour les statistiques.
  const newScore = parseInt(oldScore) + POINTS_PER_QUESTION;
  document.getElementById('score').textContent = newScore;

  // Afficher la question.
  document.getElementById('question').textContent = question;
}

// Fonction pour gérer le formulaire.
function handlePuzzleFormSubmission(event) {
  event.preventDefault(); // Empêcher le comportement par défaut du formulaire.

  const form = event.target;
  const answerInput = form.elements.answer;

  const challengeAnswer = checkAnswer(generateSimpleMathPuzzle(), parseInt(answerInput.value)); // Générer une nouvelle énigme pour vérifier la réponse.

  if (challengeAnswer) {
    nextQuestion(); // Générer une nouvelle énigme après avoir vérifié avec succès la précédente.
    answerInput.value = ''; // Effacer la réponse de l'input pour la prochaine énigme.
  } else {
    alert(`Sorry, the correct answer is ${generateSimpleMathPuzzle().result}.`);
    answerInput.value = ''; // Effacer la réponse de l'input pour la prochaine énigme.
  }
}

// Génère un nouveau puzzle et affiche la première énigme.
nextQuestion();

// S'associe au formulaire pour gérer son évenement de soumission.
document.querySelector('#puzzle-form').addEventListener('submit', handlePuzzleFormSubmission);
