Premièrement, créez un objet qui contiendra les fonctions pour gérer le jeu :

```javascript
class MathGame {
  constructor() {
    this.score = 0; //.Total game score
    this.questionsTotal = 10; //Total number of questions
    this.currentQuestionIndex = 0; //Index of current question
  }

  //Function to generate a new math question
  generateQuestion() {
    const minNumber = 1;
    const maxNumber = 20;
    const firstTerm = Math.floor(Math.random() * (maxNumber - minNumber + 1)) + minNumber;
    const operator = Math.random() < 0.5 ? '+' : '-';
    const secondTerm = Math.floor(Math.random() * (maxNumber - minNumber + 1)) + minNumber;
    const question = `${firstTerm} ${operator} ${secondTerm}`;
    const answer = this.calculateAnswer(firstTerm, operator, secondTerm);
    return { question, answer };
  }

  //Function to calculate the answer of the math question
  calculateAnswer(a, op, b) {
    if (op === '+') return a + b;
    else if (op === '-') return a - b;
  }

  //Function to handle user input for a question
  async answerQuestion(answer) {
    const currentQuestion = this.getQuestion();
    if (currentQuestion.answer === answer) {
      this.score++; //Increment score if answer is correct
      console.log(`Bravo ! Votre réponse est correcte. Points additionnels: +1`);
    } else {
      console.log(`Votre réponse était fausse. Réponse attendue: ${currentQuestion.answer}`);
    }
    this.nextQuestion();
  }

  //Function to get the current question object
  getQuestion() {
    if (this.currentQuestionIndex >= this.questionsTotal) {
      throw Error("Les questions sont terminées");
    }
    const question = this.generateQuestion();
    this.currentQuestionIndex++;
    return question;
  }

  //Function to go to the next question
  nextQuestion() {
    if (this.currentQuestionIndex >= this.questionsTotal) {
      console.log(`Fin du jeu. Votre score final: ${this.score}`);
    } else {
      console.log(`Nouvelle question en cours...`);
    }
  }

  //Function to start the game
  startGame() {
    console.log("Bienvenue à l'Académie des maths ! 📚");
    console.log(`Vous aurez ${this.questionsTotal} questions à résoudre.`);
    console.log("Voici les règles du jeu:");

    for (let I = 0; I < this.questionsTotal; i++) {
      try {
        const currentQuestion = this.getQuestion();
        console.log(`Question ${i + 1}: ${currentQuestion.question}`);
        const answer = await this.getUserInput();
        this.answerQuestion(answer);
      } catch (error) {
        console.error(error.message);
      }
    }
  }

  //Function to get user input for the current question
  async getUserInput() {
    return new Promise((resolve) => {
      process.stdin.resume();
      process.stdin.setEncoding("utf8");
      process.stdin.write(`Répondez à la question ${this.currentQuestionIndex}: `);
      let input = "";
      process.stdin.on("data", (chunk) => {
        input += chunk;
      });
      process.stdin.on("end", () => {
        resolve(parseFloat(input.trim()));
      });
    });
  }
}

// Create a new MathGame instance and start the game
const game = new MathGame();
game.startGame();
```

