// fonction qui génère une énigme mathématique au hasard avec des nombres entre min et max
function generateArithmeticProblem(min, max) {
  const num1 = Math.floor(Math.random() * (max - min + 1)) + min;
  const num2 = Math.floor(Math.random() * (max - min + 1)) + min;
  const operator = Math.random() < 0.5 ? '+' : '-';
  let problemStr = `${num1} ${operator} ${num2}`;

  // dans le cas d'une soustraction, vérifier que le second nombre ne dépasse pas la valeur maximale
  if (operator === '-') {
    while (num1 - num2 > max) {
      num1 = Math.floor(Math.random() * (max - min + 1)) + min;
      num2 = Math.floor(Math.random() * (max - min + 1)) + min;
      problemStr = `${num1} ${operator} ${num2}`;
    }
  }

  return { problem: problemStr, solution: eval(problemStr) };
}

// fonction principale du jeu
function playArithmeticMathGame() {
  // initialiser le score
  let score = 0;

  // boucle de jeu
  while (true) {
    // générer une énigme mathématique
    const problem = generateArithmeticProblem(1, 50);
    const { problem: question, solution: answer } = problem;

    // demander à l'utilisateur la réponse
    const userAnswer = prompt(`Quel est la valeur de ${question}?`);

    // vérifier la réponse
