// Define a function that generates a customized activity itinerary for 7 days in London, based on the specified rules
List<TouristActivity> GenerateActivityItinerary(List<TouristActivity> allActivities)
{
    // 1. Filter activities based on their intelligence types
    Dictionary<string, List<TouristActivity>> activityByIntelligenceType = allActivities
        .GroupBy(act => act.IntelligenceTypes.Select(it => it.Name).ToList())
        .ToDictionary(grp => string.Join(",", grp.Key), grp => grp.ToList());

    // 2. Find the activities that are geographically close to each other
    Dictionary<string, List<TouristActivity>> closeActivities = new Dictionary<string, List<TouristActivity>>();
    foreach (var activity in allActivities)
    {
        string locationKey = activity.Location;
        if (!closeActivities.ContainsKey(locationKey))
        {
            closeActivities[locationKey] = new List<TouristActivity> { activity };
        }
        else
        {
            closeActivities[locationKey].Add(activity);
        }
    }

    // 3. Filter activities based on their season availability
    DateTime startDate = DateTime.Now.AddDays(7); // assume the tourist is visiting in the next week
    List<TouristActivity> activitiesBySeason = new List<TouristActivity>();
    foreach (Season season in Enum.GetValues(typeof(Season)))
    {
        activitiesBySeason.AddRange(allActivities.Where(act => act.Availability.IsInSeason(startDate))
                                                  .ToList());
        startDate = startDate.AddMonths(1); // Move to the next month
    }

    // 4. Generate the itinerary
    List<TouristActivity> itinerary = new List<TouristActivity>();
    Random rand = new Random();

    // Ensure each intelligence type is included at least once
    foreach (var intelligenceTypes in activityByIntelligenceType.Values)
    {
        TouristActivity selectedAct = intelligenceTypes[rand.Next(intelligenceTypes.Count)];
        itinerary.Add(selectedAct);
    }

    // Add close activities until max capacity reached (ideally 2 per day)
    List<string> visitedLocations = new List<string>();
    int maxCapacityPerDay = 2;
    for (int I = 1; I <= 7; i++) // 7 days itinerary
    {
        List<TouristActivity> availableActs = new List<TouristActivity>();
        foreach (var closeActs in closeActivities.Values)
        {
            bool isVisited = visitedLocations.Contains(closeActs[0].Location);
            if (isVisited)
            {
                continue;
            }

            int actsCount = itinerary.Count(x => x.Location == closeActs[0].Location);
            if (actsCount < maxCapacityPerDay)
            {
                availableActs.AddRange(closeActs);
            }
        }

        if (availableActs.Count == 0)
        {
            break;
        }

        int randIndex = rand.Next(availableActs.Count);
        TouristActivity selectedAct = availableActs[randIndex];
        itinerary.Add(selectedAct);

        visitedLocations.Add(selectedAct.Location);
    }

    // Add an activity from each season
    List<TouristActivity> itineraryWithSeasons = new List<TouristActivity>(itinerary);
    foreach (Season season in Enum.GetValues(typeof(Season)))
    {
        TouristActivity selectedSeasonAct = activitiesBySeason
            .Where(act => act.Availability == season)
            .OrderByDescending(act => rand.Next())
            .FirstOrDefault(); // Randomly select one if more than one activity found
        itineraryWithSeasons.Add(selectedSeasonAct);
    }

    // Shuffle the itinerary (optional)
    int n = itineraryWithSeasons.Count;
    while (n > 1)
    {
        int k = rand.Next(n);
        n--;
        TouristActivity temp = itineraryWithSeasons[n];
        itineraryWithSeasons[n] = itineraryWithSeasons[k];
        itineraryWithSeasons[k] = temp;
    }

    return itineraryWithSeasons;
}

