        Mathematiques,
        EspacesVisuelsEtFormes,
        Musicaux,
        Bodin,
        Interpersonnel,
        Intrapersonnel,
        LogiqueMathematique,
        NaturelleHistoire,
        InteretSocial,
        Solidaire,
        Artistique,
        Moral,
        Existentielle,
        Intuitionnel,
        Kinesthésique
    }

