    {
        public string Name { get; set; }
        public string Description { get; set; }
        public System.Drawing.PointF GPSCoordinates { get; set; }
        public Season RelatedSeason { get; set; }
        public MultiplieIntelligences MultipleIntelligences { get; set; }
    }

    public void GenerateItinerary()
    {
        // Seed activites
        SeedActivities();

        // 1. Choose one activity for each of the 16 Multiple Intelligences
        List<Tuple<Activity, MultiplieIntelligences>> activitiesByMI =
            activites.GroupBy(activity => activity.MultipleIntelligences)
                    .Select(group => group.OrderBy(activity => activity.GPSCoordinates.DistanceTo(new System.Drawing.PointF(51.5098657, -0.118092)))).First().Take(16).ToList()
                    .Select(activity => new Tuple<Activity, MultiplieIntelligences>(activity, activity.MultipleIntelligences)).ToList();

        // 2. Order activities by closest proximity
