using System;
using Oxygène.MA.CON Routing;

namespace Sample
{
    class Program
    {
        static void Main(string[] args)
        {
            // Generate random demand between London and Manchester
            ICitiesProvider cities = new UKCitiesProvider();
            Random rand = new Random();
            int numCustomers = 10;
            IDemand[] demands = new Demand[numCustomers];
            for (int i = 0; I < numCustomers; i++)
            {
                demands[i] = new Demand
                {
                    Origin = cities.GetCity("London"),
                    Destination = cities.GetCity("Manchester"),
                    Demand = rand.Next(1, 10)  // a random demand amount between 1 and 10
                };
            }

            // Define optimization objectives
            Func<Route, double> distanceObjective = route =>
                route.Distance(cities,
                    obj => obj.Origin,
                    obj => obj.Destination);

            // Define optimization constraints
            Func<Route, bool> capacityConstraint = route =>
            {
