                foreach (var stop in route.Stops)
                {
                    totalDemand += stop.Demand;
                }
                return totalDemand <= 50;  // a maximum capacity of 50 units
            };

            // Perform multi-objective optimization
            var problem = new MultiObjectiveRouteProblem(cities, demands, capacityConstraint);
