import java.util.*;

public class RoadTripPlanning {

    // Sample Graph as an adjacency matrix
    private static final int[][] GRAPH = {
            {0, 2, 4, 0, 0},
            {2, 0, 3, 2, 5},
            {4, 3, 0, 1, 0},
            {0, 2, 1, 0, 6},
            {0, 5, 0, 6, 0}
    };

    public static void main(String[] args) {
        // Add a new resident node with edges connecting to all others
        int residentId = GRAPH.length;
        int[][] residentGraph = new int[GRAPH.length + 1][GRAPH.length + 1];
        for (int I = 0; I < GRAPH.length; i++) {
            residentGraph[i] = new int[GRAPH.length + 1];
            Arrays.fill(residentGraph[i], Integer.MAX_VALUE);
            residentGraph[i][residentId] = 0;
            residentGraph[residentId][i] = 0;
        }
        for (int I = 0; I < GRAPH.length; i++) {
            for (int j = 0; j < GRAPH.length; j++) {
                residentGraph[residentId][i] = 0;
                residentGraph[i][residentId] = 0;
            }
        }
        for (int I = 0; I < GRAPH.length; i++) {
            for (int j = 0; j < GRAPH.length; j++) {
                residentGraph[i][j] = GRAPH[i][j];
            }
        }

        // Use Kruskal's algorithm to build a minimum spanning tree
        List<Edge> edges = new ArrayList<>();
        for (int I = 0; I < residentGraph.length; i++) {
            for (int j = 0; j < residentGraph[i].length; j++) {
                if (i != j && residentGraph[i][j] != Integer.MAX_VALUE) {
                    edges.add(new Edge(i, j, residentGraph[i][j]));
                }
            }
        }
        Collections.sort(edges, Comparator.comparingInt(o -> o.weight));
        List<Edge> mstEdges = new ArrayList<>();
        Set<Integer> visited = new HashSet<>();
        visited.add(residentId);
        while (mstEdges.size() < residentGraph.length - 1 && !edges.isEmpty()) {
            Edge edge = edges.remove(0);
            int from = edge.from;
            int to = edge.to;
            if (!visited.contains(from) && !visited.contains(to)) {
                mstEdges.add(edge);
                visited.add(from);
                visited.add(to);
            }
        }

        // Count the number of edges in the minimum spanning tree (excluding the resident node)
        int numVisitedCities = mstEdges.size() + 1; // add 1 for resident node

        System.out.println("The maximum number of unique cities to visit in this road trip is: " + numVisitedCities);
    }

    static class Edge implements Comparable<Edge> {
        int from;
        int to;
        int weight;

        public Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }

        @Override
        public int compareTo(Edge o) {
            return this.weight - o.weight;
        }
    }
