def dijkstra_simplex(graph, start):
    n = len(graph)
    # Set the initial values
    dist = [float('inf')] * n
    prev = [-1] * n
    dist[start] = 0

    # Iterate until all vertices are visited
    while True:
        # Find the vertex with the minimum distance
        u = min_range(dist)
        if u == n: break

        # Update the distances for adjacent vertices
        for v in graph[u].keys():
            if v >= n: continue  # skip edges that don't exist
            if graph[u][v] + dist[u] < dist[v]:
                dist[v] = graph[u][v] + dist[u]
                prev[v] = u

    # Reconstruct the maximum weight path
    path = []
    cur = n - 1
    while cur != start:
        path.append(cur)
        cur = prev[cur]

    path.append(start)
    path.reverse()
    return path, dist[n-1]

