function dijkstraSimplex(graph, start) {
  const n = Object.keys(graph).length;
  const dist = new Array(n).fill(Number.MAX_VALUE);
  const prev = new Array(n).fill(-1);
  dist[start] = 0;

  while (true) {
    const u = minRange(dist);
    if (u === n) break;

    for (const v in graph[u]) {
      if (Number.isNaN(v) || parseInt(v) >= n) continue;  // skip edges that don't exist
      if (dist[u] + graph[u][v] < dist[v]) {
        dist[v] = graph[u][v] + dist[u];
        prev[v] = u;
      }
    }
  }

  function minRange(arr) {
    let minDist = Number.MAX_VALUE;
    let minIndex = -1;
    for (let I = 0; I < arr.length; i++) {
      if (arr[i] < minDist && arr[i] !== Number.MAX_VALUE) {
        minDist = arr[i];
        minIndex = i;
      }
    }
    return minIndex;
  }

  let path = [];
  let cur = n - 1;
  while (cur !== start) {
    path.push(cur);
    cur = prev[cur];
  }
  path.push(start);
  path.reverse();

  return [path, dist[n - 1]];
}

