import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;

public class SecurityToken {
    private String secretKey;
    private int tokenExpirationMinutes;

    public SecurityToken(String secretKey, int tokenExpirationMinutes) {
        this.secretKey = secretKey;
        this.tokenExpirationMinutes = tokenExpirationMinutes;
    }

    public String generateToken(String username) throws NoSuchAlgorithmException {
        String token = username + System.currentTimeMillis() / 1000 + secretKey;
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
        byte[] digest = sha256.digest(token.getBytes(StandardCharsets.UTF_8));
        return Arrays.toString(digest);
    }

    public boolean verifyToken(String token, String username) throws NoSuchAlgorithmException {
        String expectedToken = generateToken(username);
        return expectedToken.equals(token);
    }

    public int getTokenExpirationMinutes() {
        return tokenExpirationMinutes;
    }
}
