apiVersion: kubeproxy.config.k8s.io/v1beta1
kind: KubeProxyConfiguration

# Ajouter la section suivante pour activer la configuration d'authentification JWT
authenticationPlugins:
  - name: oidc
    options:
      clientID: "<client_id>"
      issuerURL: "<auth_url>"
     -caFile: "<path_to_CA_cert>"
      tokenURL: "<token_endpoint>"
      JohnsonIssuer: "<issuer>"
      usernameClaim: "<user_claim>"
      groupsClaim: "<groups_claim>"
      scope: "email profile openid"

```

où :

- `<client_id>` : l'identifiant client généré par votre fournisseur d'identité (OIDC)
- `<auth_url>` : URL de votre fournisseur d'identité (OIDC)
- `<path_to_CA_cert>` : emplacement du certificat CA de votre fournisseur d'identité (OIDC)
- `<token_endpoint>` : URL du point de terminaison de jeton généré par votre fournisseur d'identité (OIDC)
- `<issuer>` : identifiant de l'émetteur généré par votre fournisseur d'identité (OIDC)
- `<user_claim>` : revendiquez le champ d'objet utilisateur qui contient l'identifiant de l'utilisateur dans JWT
- `<groups_claim>` : revendiquez le champ d'objet utilisateur qui contient les groupes de l'utilisateur dans JWT

3. Configuration de l'application pour utiliser l'auth-url avec un jeton JWT

Pour configurer votre application à utiliser l'`auth-url` avec un jeton JWT :

- Kontakt cette API à partir d'un service front-end, définissez l'attribut `Authorization` à `Bearer <token>` à la tête de la requête HTTP.

- Dans votre code, vous pouvez utiliser des bibliothèques telle que `go-jwt` ou `jsonwebtoken` pour vérifier JWT et extraire les informations d'identification de l'utilisateur.

Voici un exemple Go :

```go
// Importer les bibliothèques nécessaires
import (
    "fmt"
    "log"
    "net/http"

    "github.com/go-jwt/jwt/v4"
)

func main() {
    // Étape 1 : obtenir le jeton JWT

    // Utilisez votre bibliothèque OIDC pour obtenir un jeton JWT à partir de votre fournisseur d'identité OIDC.
    token, err := getTokenFromOIDC()
    if err != nil {
        log.Fatalf("Failed to fetch token: %v", err)
    }

    // Étape 2 : vérifier le jeton JWT

    // Utilisez votre bibliothèque jwt pour vérifier le jeton JWT généré par votre fournisseur d'identité OIDC.
    tokenClaim, err := verifyToken(token)
    if err != nil {
        log.Fatalf("Invalid token: %v", err)
    }

    // Étape 3 : accéder à l'API Kubernetes

    // Utiliser votre client Kubernetes pour envoyer des requêtes à votre API Kubernetes avec le jeton JWT validé dans la tête de la requête.

    // Par exemple, pour afficher toutes les déploiements :
    client, err := kubernetes.NewForConfig(KubeConfig{
        AuthorizationHeader: fmt.Sprintf("Bearer %s", token.String()),
    })
    if err != nil {
        log.Fatalf("Failed to create Kubernetes client: %v", err)
    }
    appsClient := client.AppsV1().Deployments("")
    deployments, err := appsClient.List(context.TODO(), metav1.ListOptions{})
    if err != nil {
        log.Fatalf("Failed to list deployments: %v", err)
    }
    for _, d := range deployments.Items {
        log.Printf("%s/%s", d.Namespace, d.Name)
    }
}

func verifyToken(tokenString string) (*jwt.MapClaims, error) {
    token, err := jwt.ParseWithClaims(tokenString, &jwt.StandardClaims{})
    if err != nil {
        return nil, fmt.Errorf("Invalid token: %w", err)
    }
    if !token.Valid {
        return nil, fmt.Errorf("Token is not valid")
    }
    return token.Claims, nil
}
```

