async function getToken() {
  // Connexion avec vos credentials d'application de Keycloak pour récupérer le token JWT
  const response = await axios.post(
    `${keycloakUrl}/.auth/realms/${process.env.KEYCLOAK_DOMAIN}/protocol/openid-connect/token`,
    new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: clientId,
      client_secret: clientSecret,
    }),
    {
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      responseType: 'token id_token',
      withCredentials: false,
      params: {
        scope: 'roles',
        response_type: 'token id_token',
        redirect_uri: 'http://localhost:3000/callback',
      },
    },
  );

  // Extraire le token JWT de la réponse
  const accessToken = response.data.access_token;
  const idToken = response.data.id_token;

  // Changer le domaine pour le placer dans le Format d'URL JWKS
  const kid = idToken.payload['kid'].replace(`${keycloakDomain}/`, '');

  // Obtenir le certificat public dans le Format JWKS
  const jwksClient = jwksRsa({
    cache: true,
    rateLimit: true,
    jwksRequests: {
      [`${keycloakUrl}/auth/realms/${process.env.KEYCLOAK_DOMAIN}/protocol/openid-connect/certs`]: () =>
        axios.get(
          `${keycloakUrl}/auth/realms/${process.env.KEYCLOAK_DOMAIN}/protocol/openid-connect/certs`,
          {
            headers: {
              'Content-Type': 'application/json',
            },
            responseType: 'json',
            withCredentials: false,
          },
        ),
    },
  });

  // Créer une fonction pour signer les jetons
  const signToken = async () => {
    const key = await jwksClient.getSigningKey(kid);
    const signingKey = key.getSigningKey();

    return jwt.sign({ sub: 'client_id' }, Buffer.from(signingKey.getPublicKey(), 'base64'), {
      algorithm: 'RS256',
      expiresIn: '15m',
    });
  };

  const token = await signToken();

  return token;
}

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
