import random

from abc import ABC, abstractmethod

class UserBehaviorModel(ABC):
    @abstractmethod
    def calculate_user_behavior(self, context):
        pass

class MachineLearningModel(UserBehaviorModel):
    def __init__(self, model):
        self.model = model

    def calculate_user_behavior(self, context):
        prediction = self.model.predict(context)
        return prediction

class SocialAgentModel(UserBehaviorModel):
    def __init__(self, initial_strategy, social_network):
        self.strategy = initial_strategy
        self.social_network = social_network

    def calculate_user_behavior(self, context):
        agent_behavior = self.strategy.calculate_behavior(self.social_network, context)
        return agent_behavior

class OperationalModel(UserBehaviorModel):
    def __init__(self, choice_model):
        self.choice_model = choice_model

    def calculate_user_behavior(self, context):
        choice = self.choice_model.make_choice(context)
        return choice
```

