import numpy as np

class InitMLStrategy:
    def __init__(self, model, data):
        self.model = model
        self.data = data

    def fit(self):
        self.model.fit(self.data)

class RandomStrategy:
    def calculate_behavior(self, social_network, context):
        return random.choice(social_network)

class ProbabilisticChoiceModel:
    def __init__(self, parameters):
        self.parameters = parameters

    def fit(self, data):
        self.profit_matrix = data['profit']
        self.saliency_matrix = data['saliency']
        self.context_size = len(data['context'])
        self.utility_function = lambda x, y: self.profit_matrix[x, y] + self.saliency_matrix[x, y]

    def make_choice(self, context):
        choices = list(range(len(self.profit_matrix)))
        utilities = []
        for I in choices:
            utility = sum([self.utility_function(i, choice) for choice in context])
            utilities.append(utility)

        probabilities = self._softmax(utilities)
        return np.random.choice(choices, p=probabilities)

    @staticmethod
    def _softmax(x):
        e_x = np.exp(x - np.max(x))
        return e_x / e_x.sum()
```

