Voici une solution en C++ pour créer un simple préprocesseur GLSLX incluant les directives `#include` :

1. Créez un projet C++ ou ajoutez les obligations suivantes :

   - Fichier d'en-tête : `include_parser.h`

   ```cpp
   #ifndef INCLUDE_PARSER_H_
   #define INCLUDE_PARSER_H_

   #include <fstream>
   #include <iostream>
   #include <string>

   #define GLSLX_FILEPATH_MAX_LENGTH 1024

   struct IncludeParser {
     std::string processFile(const std::string& filePath);

     // Add files to include search path
     void setSearchPaths(const std::vector<std::string>& paths);

     // Add a file to include search path
     void setSearchPath(const std::string& path);

     // Disable filesystem access which makes IncludeParser a pure string manipulation library
     void setDisableFileSystemAccess();

   private:
     std::vector<std::string> m_searchPaths;
     bool m_disableFileSystemAccess = false;
   };

   #endif  // INCLUDE_PARSER_H_
   ```

2. Créez le fichier de source principal : `include_parser.cpp`

   ```cpp
   #include "include_parser.h"

   using namespace std;

   // Helper function to read file's contents into a string
   string readFileContents(const string& filePath) {
     ifstream file(filePath);
     string contents;
     file.seekg(0, ios::end);
     contents.resize(file.tellg());
     file.seekg(0, ios::beg);
     file.read(&contents[0], contents.size());
     file.close();
     return contents;
   }

   // Parse and expand #include directives
   string IncludeParser::processFile(const string& filePath) {
     string contents = readFileContents(filePath);

     // Handle #include directives
     size_t pos = 0;
     while ((pos = contents.find("#include ", pos)) != string::npos) {
       pos += 9;  // Skip #include keyword

       // Find end of include filename
       size_t endPos = contents.find_first_of("\n", pos);

       // Ensure include filename is within file
       if (endPos == string::npos) {
         endPos = contents.size();
       }

       string includeFilename = contents.substr(pos, endPos - pos);

       // Check if filename is already absolute path
       bool isAbsolutePath = (includeFilename[0] == '/');
       if (!isAbsolutePath) {
         // Search for file in include search paths
         string foundFilePath;
         for (const auto& includePath : m_searchPaths) {
           foundFilePath = includePath + "/" + includeFilename;
           if (isAbsolutePath || ifstream(foundFilePath)) {
             break;  // File found, move on to next iteration
           }
         }
         if (foundFilePath.empty()) {
           if (!m_disableFileSystemAccess) {
             cerr << "Error: File not found: " << includeFilename << endl;
           }
           // Skip unresolved include directive
           pos = endPos + 1;
           continue;
         }
         contents.replace(pos, endPos - pos, readFileContents(foundFilePath));
       } else {
         contents.replace(pos, endPos - pos, includeFilename);
         pos += includeFilename.length();  // Move pos past already replaced string
       }

       pos += 1;  // Move past newly placed include
     }

     return contents;
   }

   void IncludeParser::setSearchPaths(const vector<string>& paths) {
     m_searchPaths = paths;
   }

   void IncludeParser::setSearchPath(const string& path) {
     m_searchPaths.emplace_back(path);
   }

   void IncludeParser::setDisableFileSystemAccess() {
     m_disableFileSystemAccess = true;
   }
   ```

