         pos2++;  // Skip opening brace
         endPos = token.find('}', pos2);
         if (endPos == string::npos) {
            endPos = token.find("\n", pos2);
            if (endPos == string::npos) {
               endPos = token.size();
            }
         }
         string macroValue = token.substr(pos2, endPos - pos2);

         // Replace macro name with value
         contents = string(
               contents.substr(0, pos1 - 1) + m_macroParser->replaceMacroIfPossible(
                   macroName, macroValue) + contents.substr(endPos + 1));
         pos1 = endPos + 1;
       }
     }

     return contents;
   }

   string MacroParser::processMacroFile(const string& fileContents) {
     std::vector<string> macroDefinitions;

     // Split macro definitions into separate lines
     size_t startPos = 0, endPos;
     while ((endPos = fileContents.find("\n#define ", startPos)) != string::npos) {
         startPos =
             endPos + 1;  // Find next macro definition (search from next line)
         string macroDefinition =
             fileContents.substr(endPos, 9);  // Extract macro definition line
         macroDefinitions.push_back(macroDefinition);
     }

     for (const auto& definition : macroDefinitions) {
         size_t pos1 = 0, pos2 = 0;
         while ((pos1 = definition.find("#define ", pos1)) != string::npos) {
            pos1 += 8;  // Skip #define keyword

            // Find end of macro definition name
            size_t endPos = definition.find(" ", pos1);

            // Ensure macro name is within definition
            if (endPos == string::npos) {
               endPos = definition.find("\n", pos1);
               if (endPos == string::npos) {
                  endPos = definition.size();
               }
            }

            string macroName = definition.substr(pos1, endPos - pos1);

            // Find opening brace of macro value
            pos1 = endPos + 1;
            pos2 = definition.find('{', pos1);
            if (pos2 == string::npos) {
               endl cout << "Error: Macro definition is missing opening brace: "
                         << macroName << endl;
               continue;
            }

            // Read macro value
            pos2++;  // Skip opening brace
            endPos = definition.find('}', pos2);
            if (endPos == string::npos) {
               endPos = definition.find("\n", pos2);
               if (endPos == string::npos) {
                  endPos = definition.size();
               }
            }
            string macroValue = definition.substr(pos2, endPos - pos2);

            // Add macro definition
            addMacroDefinitions("#define " + macroName + " " + macroValue);
         }
     }

     return contents;
   }

