use std::error::Error;
use std::fs::File;
use std::io::{BufRead, BufReader};

struct GlslIncludeProcessor {
    target_file_path: String,
    include_paths: Vec<String>,
}

impl GlslIncludeProcessor {
    fn new(target_file_path: &str, include_paths: Vec<String>) -> Self {
        GlslIncludeProcessor {
            target_file_path: String::from(target_file_path),
            include_paths,
        }
    }

    fn process(&self) -> Result<String, Box<dyn Error>> {
        let target_file_ext = self.target_file_path
            .split('.')
            .last()
            .ok_or_else(|| Box::new("Target file extension not found".into()))?;

        let mut all_includes = Vec::new();
        for include_path in &self.include_paths {
            let include_ext = include_path
                .split('.')
                .last()
                .ok_or_else(|| Box::new(format!("Invalid include file extension: {}", include_ext)?))?;

            if !include_ext.eq_ignore_ascii_case("glslx") {
                return Err(Box::new(format!(
                    "Invalid include file extension: {}. Expected 'glslx'", include_ext
                )));
            }

            let mut include_content = String::new();
            let file = File::open(include_path)?;
            let reader = BufReader::new(file);
            for line_result in reader.lines() {
                let line = line_result?;
                include_content.push_str(line);
            }
            all_includes.push(include_content);
        }

        let mut processed_content = String::new();
        for include in &all_includes {
            processed_content.push_str(include);
        }

        // Add the original target file content after all includes have been concatenated
        processed_content.push_str(&self.get_target_file_content());

        Ok(processed_content)
    }

    fn get_target_file_content(&self) -> String {
        let mut file = File::open(&self.target_file_path).expect("Failed to open target file");

        let mut content = String::new();
        file.read_to_string(&mut content).expect("Failed to read target file");

        content
    }
}

fn main() {
    let target_file_path = "target.glslx";
    let include_paths = vec!["include1.glslx", "include2.glslx"];

    let mut processor = GlslIncludeProcessor::new(target_file_path, include_paths);

    let processed_content = processor.process().unwrap();

    // Save the processed content
    std::fs::write(target_file_path, processed_content).expect("Failed to write file");
}
