// Glsl preprocessor function
std::string preprocessGLSL(const std::string& glsl, const std::string& include_dir) {
    // Split the GLSL file into lines
    std::stringstream ss(glsl);
    std::string line;
    std::vector<std::string> lines;
    while (std::getline(ss, line)) {
        lines.push_back(line);
    }

    // Create output stream for processed GLSL
    std::stringstream out;

    // Loop through the lines
    for (const auto& l : lines) {
        if (l.find("#include") != std::string::npos) {
            // If line starts with #include directive
            std::string include_file = l.substr(l.find("<")+1, l.find(">") - l.find("<") - 1); // Extract included file name
            std::string path = include_dir + "/" + include_file; // Construct the full path to the included file
            std::string included_content;
            std::ifstream included_file(path);
            if (included_file.is_open()) {
                included_content.assign((std::istreambuf_iterator<char>(included_file)),
                                          std::istreambuf_iterator<char>());
                included_file.close();
            }
            out << included_content << std::endl; // Append included file content to output
        } else {
            out << l << std::endl; // Append non-included line to output
        }
    }

    return out.str();
}

