#include <stdio.h>
#include <iostream>
#include <fstream>
#include <string>
#include <vector>

// Fonction de lecture de fichier GLSLX
std::string ReadGLSLXFile(const std::string& filename) {
  std::ifstream file(filename, std::ios::binary);
  std::string content;
  if (file.is_open()) {
    file.seekg(0, std::ios::end);
    file.seekg(0, std::ios::beg);
    content.reserve(static_cast<size_t>(file.tellg()));
    file.read(&content[0], content.capacity());
    file.close();
  }
  return content;
}

// Fonction de préprocessement du contenu GLSLX
std::string PreprocessGLSLX(const std::string& glsl_contents) {
  std::string result;
  int line_offset = 0;

  std::vector<size_t> include_offsets;  // Positions des étiquettes #include

  bool inside_include = false;  // Utilisé pour gérer le contenu inclut

  for (size_t I = 0; I < glsl_contents.find("#include", 0) != std::string::npos; ) {
    size_t include_offset = glsl_contents.find("#include", I);
    if (include_offset != std::string::npos) {
      include_offsets.push_back(include_offset + line_offset);
      line_offset += glsl_contents.find('\n', include_offset + 1) + 1;  // Saute à la ligne suivante
      inside_include = true;
      result += glsl_contents.substr(include_offset, glsl_contents.find("\n", include_offset + 1) - include_offset + 1);
    } else {
      break;
    }
  }

  if (inside_include) {
    for (size_t I : include_offsets) {
      std::string include_file = ReadGLSLXFile(glsl_contents.substr(i, glsl_contents.find('\n', i) - I + 1).substr(10));  // Saisissez le nom de fichier de la ligne incluse
      int offset = I + glsl_contents.find('\n', i) + 1;  // Offset pour placer le contenu du fichier inclus
      int line_offset_include = 0;  // Compteur de lignes pour le contenu du fichier inclus

      size_t insertPos = offset;
      std::string replacements;
      int include_line = 1;

      // Analyse et remplace les étiquettes #line dans le contenu du fichier inclus
      while ((offset = include_file.find("#line", offset)) != std::string::npos) {
        // Positionneligne eticolon dans une étiquette #line
        size_t next = include_file.find_first_not_of("0123456789", offset + 6);
        size_t line = std::stoi(include_file.substr(offset + 6, next - offset - 6));
        next = include_file.find_first_of(",", next) == std::string::npos ? include_file.find_last_not_of("\r\n") + 1 : include_file.find(",", next) + 1;
        size_t column = next == std::string::npos ? 0 : std::stoi(include_file.substr(next + 1, include_file.find_first_not_of("0123456789", next + 1) - next - 1));
        include_file.replace(offset, next - offset + 1, "");

        replacements += include_file.substr(line_offset_include, line - 1 - line_offset_include) + "\n";
        line_offset_include = line;

        // Insertion dans le contenu du GLSLX initial
        insertPos += replacements.size();
        result.insert(insertPos, include_file.substr(line_offset_include, line - 1 - line_offset_include));
        replacements += std::to_string(line + include_line++) + ":" + std::to_string(column) + "\n";
        offset += replacements.size();
      }

      replacements += include_file.substr(line_offset_include);
      line_offset_include += replacements.size();

      result.replace(insertPos, offset - insertPos, replacements);
      inside_include = false;
    }
  }

  result.erase(result.find_last_not_of("\n") + 1);
  result.erase(0, result.find_first_not_of("\n"));

  return result;
}

