5. Ensuite, vous pouvez insérer le contenu du fichier inclut directement dans le flux GLSLX original pour obtenir un unique flux composé, qui est ensuite enregistré dans un nouveau fichier avec une extension GLSLX.

Voici un exemple de code pourabhérer l'inclusion de GLSLX :

```C++
#include <iostream>
#include <fstream>
#include <cstring>
#include <string>

std::string includeFileContent(std::string filePath) {
    // fonction qui lit et retourne le contenu du fichier GLSLX fourni
    std::ifstream inputFile(filePath);
    std::string content;
    std::string line;
    while(std::getline(inputFile, line)) {
        content += line + "\n";
    }
    inputFile.close();
    return content;
}

void preprocessGLSLX(std::string inputFilepath) {
    // fonction qui lit, traite et écrit le préprocesseur GLSLX
    std::ifstream input(inputFilepath);
    std::string outputContent; // contenu du fichier GLSLX final
    std::string line;
    while (getline(input, line)) {
        if (line.rfind("#include ", 0) == 0) {
            // detection de la directive #include
            std::string filePath = line.substr(line.find(" ") + 1);
            std::string includedFileContent = includeFileContent(filePath);
            outputContent += includedFileContent;
        } else {
            outputContent += line + "\n";
        }
    }
    input.close();

    // écrire le contenu GLSLX final dans un nouveau fichier
    std::string outputFilepath = inputFilepath.substr(0, inputFilepath.length() - 4) + "_preprocessed.glslx";
    std::ofstream output(outputFilepath);
    output << outputContent;
    output.close();

    std::cout << "Preprocessed GLSLX file saved: " << outputFilepath << std::endl;
}

int main() {
    preprocessGLSLX("input_file.glslx"); // appeler la fonction avec le chemin du fichier source
    return 0;
}
