5. Modifiez le code de votre script pour supporter le vol :

```csharp
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class PlayerFlyController : MonoBehaviour
{
    public float maxSpeed = 20.0f;
    public float acceleration = 20.0f;
    public float braking = 15.0f;
    public float drag = 4.0f;
    public float yawSpeed = 450.0f;

    PlayerMain player;
    Vector3 input;
    Vector3 velocity;
    Quaternion targetRotation;
    float speed;

    private void Awake()
    {
        player = GetComponent<PlayerMain>();
        targetRotation = transform.rotation;
    }

    private void Update()
    {
        HandleInput();
        ClampSpeedAndVelocity();
        Move();
        Rotate();
        ApplyDrag();
    }

    private void HandleInput()
    {
        input.x = Input.GetAxis("Vertical") * maxSpeed;
        input.y = Input.GetAxis("Horizontal");
        targetRotation = Quaternion.Euler(0, input.y * yawSpeed, 0);
    }

    private void ClampSpeedAndVelocity()
    {
        // Ensure that speed is between 0 and maxSpeed
        speed = Mathf.Clamp01(speed + (input.magnitude - speed) * Time.deltaTime);

        // Ensure that velocity magnitude is between 0 and speed
        velocity = (velocity.normalized * Mathf.Lerp(velocity.magnitude, speed, acceleration * Time.deltaTime))
            + (input.normalized * (maxSpeed - velocity.magnitude) * acceleration * Time.deltaTime);

        // Ensure that braking is not overpowering acceleration
        velocity = (velocity.normalized * Mathf.Max(velocity.magnitude - braking * Time.deltaTime, 0));
    }

    private void Move()
    {
        player.ApplyMovementInput(velocity);
    }

    private void Rotate()
    {
        transform.rotation = Quaternion.Lerp(transform.rotation, targetRotation, Time.deltaTime);
    }

    private void ApplyDrag()
    {
        velocity *= 1.0f - drag * Time.deltaTime;
    }
}
```

