            float AirSpeed = 0.0f;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            float Altitude = 0.0f;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            float AirTime = 0.0f;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight, meta = (ToolTip = "Maximum altitude of the vehicle when no thrust is applied."))
            float MaxFlyHeight = 500.0f;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            bool bIsFlying = false;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            bool bIsDrifting = false;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            bool bEnableThrust = true;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            float Gravity = 9.82f;

            UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = Flight)
            float AirResistance = 0.07f;

            // ...

            void ApplyFlightMovementInput(float DeltaTime);
