         b. Implémentez les fonctions suivantes :

            ```cpp
            // Fonctions de voler (appelées par UWorld::TickComponent())
            void FlightComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorTimeCode TimeCode)
            {
                Super::TickComponent(DeltaTime, TickType, TimeCode);
                if (Owner)
                {
                    if (!bIsFlying && bEnableThrust && (Pitch > -THRESHOLD_ANGLE || Pitch < THRESHOLD_ANGLE) && (Yaw > -THRESHOLD_ANGLE || Yaw < THRESHOLD_ANGLE))
                    {
                        ApplyFlightMovementInput(DeltaTime);
                    }
                    else
                    {
                        // Le joueur relâche le contrôle de vol / ajoute de la poussée horizontale
                        StopFlightMovement(DeltaTime);
                    }
                }
            }

            void FlightComponent::ApplyFlightMovementInput(float DeltaTime)
            {
                FVector NewVelocity;
                FVector GravityForce(VERTICAL_GRAVITY_FORCE, 0.0f, -VERTICAL_GRAVITY_FORCE);
                FVector AirResistanceForce(-AirResistance * AirSpeed, 0.0f, AirResistance * AirSpeed);

                // Calculer la trajectoire de vol en fonction de la pression / propulsion
                NewVelocity += DeltaTime * Thrust * FLY_SPEED_MULTIPLIER;
                NewVelocity += GravityForce * DeltaTime;
                NewVelocity += AirResistanceForce * DeltaTime;

                // Récupérer la nouvelle position / orientation
                FVector NewLocation = Owner->GetActorLocation() + (NewVelocity * DeltaTime);
                FRotator NewRotation = Owner->GetActorRotation();

                // Limiter l'altitude maximale / minimale
                if (NewLocation.Z > MaxFlyHeight)
                {
                    NewLocation.Z = MaxFlyHeight;
                }

                if (NewLocation.Z < MIN_FLY_HEIGHT)
                {
                    NewLocation.Z = MIN_FLY_HEIGHT;
                }

                // Récupérer la nouvelle vitesse et orientation
                AirSpeed = NewVelocity.Size();
                FRotator DeltaRot = NewRotation - Owner->GetActorRotation();
                if (Pitch < -DELTA_ROT_THRESHOLD || Pitch > DELTA_ROT_THRESHOLD)
                {
                    NewRotation.Roll += Pitch * DeltaTime * (Pitch < 0.0f ? -1.0f : 1.0f); // Gire par rapport à l'axe des x
                }
