function isPalindrome(str) {
  // Vérifier que la chaîne a une longueur valide
  if (str.length < 3 || str.length > 20) {
    return false;
  }

  // Réécriture de la chaîne en enlevant les caractères répétitifs
  const uniqueStr = str.split('').filter((char, index, self) => self.indexOf(char) === index).join('');

  // Vérifier si la chaîne réduite contient une voyelle et une consonne
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  const hasVowel = vowels.some(vowel => uniqueStr.toLowerCase().includes(vowel));
  const hasConsonant = !vowels.includes(uniqueStr[0].toLowerCase()) && !vowels.includes(uniqueStr[uniqueStr.length-1].toLowerCase());

  // Vérifier si la chaîne réduite est un palindrome
  const reversedStr = uniqueStr.split('').reverse().join('');
  return uniqueStr === reversedStr && hasVowel && hasConsonant;
}

