  if (chars.size !== str.length) {
    return false;
  }

  // Vérifier qu'il y a au moins une voyelle et une consonne
  const vowels = ['a', 'e', 'i', 'o', 'u'];
  const hasVowel = vowels.some(v => chars.has(v));
  const hasConsonant = chars.some(c => !vowels.includes(c.toLowerCase()));
  if (!hasVowel || !hasConsonant) {
    return false;
  }

  // La chaîne respecte toutes les contraintes, il s'agit donc d'un palindrome
  const reversedStr = str.split('').reverse().join('');
  return str === reversedStr;
}
