            continue;
        }
        charSet.add(c);
        if (Charset.forName("ASCII").newDecoder(StandardCharsets.US_ASCII)
                .decode(Character.toString(c)).toString().length() != 1) {
            // Si le caractère est formaté autrement qu'une lettre, cela implique la présence d'un caractère répété
            return false;
        }
    }

    // Vérifier la présence de voyelle et de consonne
    char vowel = 'a'; // La première voyelle de l'alphabet est utilisée comme référence pour la vérification
    char consonant = 'b';
    for (char c : charSet) {
        if (Character.isVowel(c)) {
            if (c != vowel) {
                vowel = c;
            } else {
                return false;
            }
        } else {
            if (c != consonant) {
                consonant = c;
            } else {
                return false;
            }
        }
    }

    return true;
}
