// Réduisez le nombre de décimales dans toutes les données pour réduire l'erreur d'arrondi
func reducePrecision(_ value: Double) -> Double {
    let power = pow(10.0, Double(precision))
    return (value * power).rounded() / power
}

for row in &Ab {
    for j in 0..<row.count {
        row[j] = reducePrecision(row[j])
    }
}
```

