import Foundation

// Matrice à résoudre
let A = [[2.1, -1.3, 3.2], [0.7, 4.1, -5.1], [-0.2, 3.0, 2.3]]
let b = [-3.2, 2.5, 2.6]

// Précision souhaitée en nombre de décimales
let precision: Int = 4

// Fonction de résolution du système de équations linéaires
func solveLinearSystem(A: [[Double]], b: [Double], precision: Int) -> ([Double], Bool) {
    // Copie locale des matrices originales
    var A = A
    var b = b

    // Nombre de lignes et de colonnes de la matrice A
    let n = A.count

    // Parcours des lignes de la matrice A
    for j in 0..<n {
        // Recherche de la ligne la plus grande en valeur absolue dans la colonne j
        var maxRow = j
        var maxVal = abs(A[maxRow][j])
        for I in (j+1)..<n {
            if abs(A[i][j]) > maxVal {
                maxRow = i
                maxVal = abs(A[i][j])
            }
        }

        // Si la valeur est nulle, la matrice est singulière
        if maxVal == 0 {
            return ([Double](repeating: .nan, count: n), false)
        }

        // Echange des lignes pour placer la ligne avec la plus grande valeur absolu en tête de colonne j
        if maxRow != j {
            for k in 0..<n+1 {
                let temp = A[j][k]; A[j][k] = A[maxRow][k]; A[maxRow][k] = temp
                let tempB = b[j]; b[j] = b[maxRow]; b[maxRow] = tempB
            }
        }

        // Division par le pivot pour obtenir une matrice identitaire en colonne j
        let pivot = A[j][j]
        for k in 0..<n+1 {
            A[j][k] /= pivot
            b[j] /= pivot
        }

        // Réduction des autres lignes en utilisant l'opérateur de barre oblique inverse
        for I in 0..<n {
            if I == j { continue }

            let factor = A[i][j]
            for k in 0..<n+1 {
                A[i][k] -= factor * A[j][k]
                b[i] -= factor * b[j]
            }
        }
    }

    // Rotation des lignes pour obtenir une matrice triangulaire infinie
    for j in (n-2)...0 {
        for I in j..<n-1 {
            let factor = A[i][j+1]
            for k in (j+1)..<n+1 {
                A[i][k] -= factor * A[j][k]
                b[i] -= factor * b[j]
            }
        }
    }

    // Construction du vecteur solution, en prenant en compte les erreurs d'arrondi possibles
    var x = [Double](repeating: .zero, count: n)
    for I in (0..<n).reversed() {
        let xEst = b[i] - A[i].dropFirst().reduce(.zero, +)
        let xVal = min(max(xEst, Double.MinValue), Double.MaxValue) // Garantir que la valeur tombe dans les bornes minimale et maximale supportées par les nombres de précision demandée
        x[i] = (pow(10, -Double(precision))) * round(xVal / pow(10, -Double(precision))) * pow(10, -Double(precision))
    }

    // Vérifier si le système est bien résolu (cohérence des solutions)
    var ok = true
    for I in 0..<n-1 {
        for j in (i+1)..<n {
            let res = A[i].reduce(.zero, +, transform: { $0 * x[j] }) - A[j].reduce(.zero, +, transform: { $0 * x[i] })
            if abs(res) > abs(x[i]) * Double.ulpOfOne {
                ok = false
                break
            }
        }
        if !ok {
            break
        }
    }
    return (x, ok)
}

// Exécution du code avec la matrice A et le vecteur b donnés
let result = solveLinearSystem(A: A, b: b, precision: precision)
let x = result.0
let success = result.1

// Imprimer les résultats
print("Solution du système d'équations linéaires:")
print("x1 = \(String(format: "%.\(precision)f", x[0]))")
print("x2 = \(String(format: "%.\(precision)f", x[1]))")
print("x3 = \(String(format: "%.\(precision)f", x[2]))")

print("Résolution correcte: \(success)")
```

Dans cette fonction, nous appliquons la méthode d'élimination gaussienne pour résoudre le système d'équations linéaires. Nous tenons compte de la précision souhaitée en utilisant les opérations de raffinement sur les valeurs des coordonnées du vecteur solution. Ceci est fait par l'utilisation de la fonction `round` de Swift, qui arrondit une valeur de double selon la précision demandée en utilisant la fonction `ulpOfOne`, qui correspond à la valeur de [unit in the last place](https://en.wikipedia.org/wiki/Unit_in_the_last_place) du nombre de partie fractionnaire le plus proche de zéro.

Pour vérifier la solution exactitude, nous vérifions la cohérence des solutions en calculant l'erreur en norme-1 entre les résultats de chaque équation et le produit vectoriel correspondant entre la matrice de coefficients et la solution. Nous vérifions que l'erreur est inférieure à la taille du flot nécessaire pour supporter la précision demandée. Si la condition est véritable, la solution est considérée correcte. Sinon, la solution ne sera pas considérée comme étant correcte.

