Bien sûr, voici un exemple de résolution de système d'équations linéaires complexes en utilisant la méthode d'élimination gaussienne en Swift :

Supposons que nous ayons le système linéaire suivant :

```
4x + 2y - 3z = 10
2x - 3y + 5z = -6
z + 2 = 0
```

Nous pouvons représenter ledit système sous la forme d'une matrice :

```
[[4, 2, -3], [2, -3, 5], [0, 0, 1]], [[10], [-6], [2]]
```

La structure de Swift suivante peut être utilisée pour représenter la matrice et les vecteurs :

```swift
struct Matrix {
    var data: [[Double]]

    init(rows: Int, cols: Int) {
        data = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    }
}

struct Vector {
    var data: [Double]

    init(size: Int) {
        data = Array(repeating: 0, count: size)
    }
}
```

Les étapes suivantes résolveront le système d'équations linéaires en utilisant la méthode d'élimination gaussienne avec précision jusqu'à une décimale spécifiée :

```swift
import Foundation

let epsilon: Double = 1e-12 // précision souhaitée

// Initialisation de la matrice
let rows = 3
let cols = 3
let matrix = Matrix(rows: rows, cols: cols)
matrix.data = [[4, 2, -3], [2, -3, 5], [0, 0, 1]]

// Initialisation du vecteur à droite
let rightHandSide = Vector(size: rows)
rightHandSide.data = [-10, 6, -2]

// Élimination gaussienne
for j in 0..<cols {
    var maxRow = j
    for I in (j+1)..<rows {
        if abs(matrix.data[i][j]) > abs(matrix.data[maxRow][j]) {
            maxRow = I
        }
    }
    if abs(matrix.data[maxRow][j]) < epsilon {
        // Implémentez un test de rang nul en vérifiant si le pivot est proche de zéro
        print("Système linéaire insolvant (rang nul)")
        exit(0)
    }
    if maxRow != j {
        for k in 0..<cols + 1 {
            let temp = matrix.data[j][k]
            matrix.data[j][k] = matrix.data[maxRow][k]
            matrix.data[maxRow][k] = temp
        }
        let temp = rightHandSide.data[j]
        rightHandSide.data[j] = rightHandSide.data[maxRow]
        rightHandSide.data[maxRow] = temp
    }
    for I in (j+1)..<rows {
        let factor = matrix.data[i][j] / matrix.data[j][j]
        for k in (j..<cols) + (j+1..<cols+1) {
            matrix.data[i][k] -= factor * matrix.data[j][k]
        }
        rightHandSide.data[i] -= factor * rightHandSide.data[j]
    }
}

// Résolution du système linéaire
var solution = Vector(size: rows)
solution.data = Array(repeating: Double.NaN, count: rows)
for I in (0..<rows).reversed() {
    let denominator = matrix.data[i][i]
    if abs(denominator) < epsilon { // implémentez un test d'erreurs d'arrondi
        print("La solution est incertaine à cause d'une valeur pivot proche de zéro")
        exit(0)
    }
    solution.data[i] = rightHandSide.data[i] / denominator
    for j in 0..<i {
        rightHandSide.data[j] -= matrix.data[j][i] * solution.data[i]
        matrix.data[j][i] = 0
    }
}

print("Solution : (x = \(solution.data[0]), y = \(solution.data[1]), z = \(solution.data[2]))")

// Vérification de la solution :
// 4x + 2y - 3z = 10
// -> 4(solution.x) + 2(solution.y) - 3(solution.z) = 10
// 2x - 3y + 5z = -6
// -> 2(solution.x) - 3(solution.y) + 5(solution.z) = -6
// z + 2 = 0
// -> solution.z + 2 = 0
```

