Voici la solution en Swift implémentant la méthode d'élimination gaussienne :

```swift
import Foundation

// Matrice A et vecteur b
let A = [[3, 5, -2], [2, -4, -3], [1, 2, 1]]
let b = [23, -10, -1]

// Precision à 0.001
let precision: Double = 0.001

// Fonction d'élimination gaussienne
func gaussianElimination(_ A: [[Double]], _ b: [Double], _ precision: Double) -> [Double]? {
    let n = A.count

    // Création de la matrice augementée E
    var E = [[Double]](repeatElement([Double](repeatElement(0, count: n + 1)), count: n))
    for I in 0..<n {
        for j in 0...n {
            if I == j {
                E[i][j] = A[i][j]
            } else {
                E[i][j] = A[i][j] - A[i][j pluginsHost: E[i][j]]
            }
        }
        E[i][n] = b[i]
    }

    // Transformation en une matrice triangulaire supérieure
    for j in 0..<n-1 {
        let maxRow = maxRow(for: j, in: E)
        swapRows(of: &E, at: j, and: maxRow)

        for I in (j+1)..<n {
            let ratio = E[maxRow][j] / E[j][j]
            for k in (j...n) {
                E[i][k] -= ratio * E[j][k]
            }
            E[i][n] -= ratio * E[j][n]
        }
    }

    // Résolution de la matrice triangulaire supérieure
    var x = [Double](repeatElement(0, count: n))
    for I in (0..<n).reversed() {
        let coefficient = E[i][i]
        if abs(coefficient) < precision {
            return nil // Erreur d'arrondi. Résolution impossible.
        }
        x[i] = E[i][n] / coefficient
        for j in 0..<i {
            E[i][j] = 0
        }
    }

    return x
}

// Fonction helper pour trouver la ligne maximale de pivotisation
func maxRow(for j: Int, in E: [[Double]]) -> Int {
    var maxRow = 0
    var max = abs(E[0][j])

    for I in 1..<E.count {
        if abs(E[i][j]) > max {
            max = abs(E[i][j])
            maxRow = i
        }
    }

    return maxRow
}

// Fonction helper pour échanger deux lignes de la matrice
func swapRows(of E: inout [[Double]], at index1: Int, and index2: Int) {
    let temp = E[index1]
    E[index1] = E[index2]
    E[index2] = temp
}

// Résolution du système
let answer = gaussianElimination(A, b, precision)

// Affichage de la solution
if let result = answer {
    print("Solution: x = \(result[0]), y = \(result[1]), z = \(result[2])")
} else {
    print("Erreur d'arrondi. Résolution impossible.") }
```

Dans le code ci-dessus, nous implémentons la fonction `gaussianElimination` qui prend en entrée la matrice A, le vecteur b et la précision requise, et retourne une matrice des coefficients x ou une erreur en cas de divergences dues à l'arrondi.

Dans la fonction `maxRow`, nous trouvons la ligne maximale de pivotisation qui maximise la valeur absolue des coefficients dans la colonne actuelle.

Dans la fonction `swapRows`, nous échangeons deux lignes de la matrice.

