Nous pouvons créer une carte thermique du nombre de fois qu'un module est importé en Python en utilisant les libraires `networkx` et `matplotlib`. Voici les étapes à suivre :

1. Importer les bibliothèques nécessaires :

```python
import networkx as nx
import matplotlib.pyplot as plt
import collections
```

2. Créer une fonction qui compte le nombre d'importations de chaque module :

```python
def count_module_imports(module):
    """Count the number of imports for the given module"""
    import importlib
    import os

    # Add the module to Python's search path so that we can import its dependencies
    module_path = os.path.abspath(module.__file__)
    if module_path not in sys.path:
        sys.path.append(os.path.dirname(module_path))

    # Import all the dependencies and count their appearances
    imports = collections.Counter()
    for import_name in dir(module):
        import_obj = getattr(module, import_name)
        if isinstance(import_obj, importlibMODULE):
            imports[import_name] += 1

    return imports
```

3. Collecter les informations d'importation pour tous les modules requis par un fichier Python :

```python
def get_module_import_tree(import_path):
    """Recursively collect information about module imports"""
    import importlib

    # Import the starter module and count its imports
    module = importlib.import_module(import_path)
    imports = count_module_imports(module)

    # Create a directed graph for the imports
    G = nx.DiGraph()

    # Add the root node representing the starter module
    G.add_node(import_path, size=imports[import_path])

    # Recursively add nodes for each dependency and its imports
    for dependency in module.__dict__.keys():
        if isinstance(module.__dict__[dependency], importlibMODULE):
            imported_module = dependency

            # Import the dependency module and count its imports
            imported_module_path = imported_module.__name__
            imported_imports = count_module_imports(importlib.import_module(imported_module_path))

            # Add the dependency node to the graph and connect it to the root
            G.add_node(imported_module_path, size=imported_imports[imported_module_path])
            G.add_edge(import_path, imported_module_path, weight=imported_imports[imported_module_path])

            # Recursively add nodes for any dependencies of the current dependency module
            get_module_import_tree(imported_module_path, G)

    return G
```

4. Afficher la carte thermique de l'arbre d'importation :

```python
def plot_module_import_tree(G, node=None, pos=None):
    if not pos:
        pos = nx.spring_layout(G)

    node_colors = [d['size'] for n, d in G.nodes(data=True)]

    if not node:
        node_list = list(G.nodes)
    else:
        node_list = [node]

    nx.draw_networkx_nodes(G, pos, node_list, node_size=[d['size'] * 1000 for n, d in G.nodes(data=True)], alpha=0.8)
    nx.draw_networkx_edges(G, pos, alpha=0.4)
    nx.draw_networkx_labels(G, pos, font_size=7)

    fig, ax = plt.subplots(figsize=(12, 8))

    def format_node_labels(t, n, f):
        if n in G and 'size' in G.nodes[n]:
            return '{:.2f}\n{}'.format(G.nodes[n]['size'], f(t, n))
        else:
            return f(t, n)

    ax.set_axis_off()
    nx.draw_networkx_nodes(G, pos, node_color=node_colors, ax=ax, node_size=1000, alpha=0.5, cmap='viridis')

    def node_props(t, n):
        return dict(
            bbox=dict(facecolor='white', alpha=0.5),
            ha='center',
            va='center',
            font_size=6
        )

    nx.draw_networkx_labels(G, pos, labels={n: format_node_labels(pos[n], n, plt.text) for n in G}, font_color='white', ax=ax, node_props=node_props)

    plt.show()
```

