            System.out.println("Generation " + Generation + " - Best Individual: " + population.get(0).getFitness());

            // Sélection de parents
            ArrayList<Individual> parents = selection(population);

            // Crossover entre les parents
            ArrayList<Individual> offspring = crossover(parents);

            // Mutation des enfants
            offspring.forEach(offspring1 -> offspring1.getGenes() = mutate(offspring1.getGenes()));

            // Ajouter les nouveaux enfants à la population
            population.addAll(offspring);

            // Tronquer la taille de la population au seuil de la taille souhaitée
            while (population.size() > populationSize) {
                population.remove(population.size() - 1);
            }

