            double randomNumber = random.nextDouble();
            if (randomNumber < 0.6) {
                // Selection de l'individu avec le meilleur fitness
                int parentIndex = 0;
                for (int j = 1; j < population.size(); j++) {
                    if (population.get(j).getFitness() > population.get(parentIndex).getFitness()) {
                        parentIndex = j;
                    }
                }
                selectedPopulation.add(population.get(parentIndex));
            } else if (randomNumber >= 0.6 && randomNumber < 0.8) {
                // Selection de deux ind
                int parentIndex1 = random.nextInt(population.size());
                int parentIndex2 = random.nextInt(population.size());
                while (parentIndex1 == parentIndex2) {
                    parentIndex2 = random.nextInt(population.size());
                }
                ArrayList<Individual> parents = new ArrayList<>(2);
                parents.add(population.get(parentIndex1));
                parents.add(population.get(parentIndex2));
                selectedPopulation.addAll(parents);
            } else {
                // Selection de l'individu aléatoire
                int parentIndex = random.nextInt(population.size());
                selectedPopulation.add(population.get(parentIndex));
            }
        }
        return selectedPopulation;
    }

    private ArrayList<Individual> crossover(ArrayList<Individual> parents) {
        int numOfParents = parents.size();
        ArrayList<Individual> offspring = new ArrayList<>(numOfParents);
        for (int I = 0; I < numOfParents - 1; i += 2) {
            Individual parent1 = parents.get(i);
            Individual parent2 = parents.get(i + 1);
            int crossoverPoint = random.nextInt(parent1.getGenes().length);
            int[] child1Genes = Arrays.copyOfRange(parent1.getGenes(), 0, crossoverPoint);
            int[] child2Genes = Arrays.copyOfRange(parent2.getGenes(), crossoverPoint, parent2.getGenes().length);
            child1Genes = merge(child1Genes, Arrays.copyOfRange(parent2.getGenes(), 0, crossoverPoint));
            child2Genes = merge(child2Genes, Arrays.copyOfRange(parent1.getGenes(), crossoverPoint, parent1.getGenes().length));
            offspring.add(new Individual(child1Genes));
            offspring.add(new Individual(child2Genes));
        }
        if (offspring.size() % 2 != 0) {
            offspring.add(parents.get(offspring.size() - 1));
        }
        return offspring;
    }

    private int[] merge(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }

    private int[] mutate(int[] genes) {
        for (int I = 0; I < genes.length; i++) {
            if (random.nextDouble() < mutationRate) {
                genes[i] = random.nextInt(maxClusters) + minClusters - 1;
            }
        }
        return genes;
    }

}
```

