{
    // Créer un contexte Asio
    boost::asio::io_context ioc;

    // Créer un socket TCP
    boost::asio::ip::tcp::socket socket(ioc);

    // Connecter le socket à un serveur distant
    boost::asio::ip::tcp::endpoint endpoint(boost::asio::ip::address::from_string("192.168.1.100"), 8080); // Replace the IP address, port number with the values for the server you wish to connect to
    socket.connect(endpoint);

    // Envoi de données sur le socket
    boost::asio::write(socket, boost::asio::buffer("Hello, server! "));

    // Lecture de données reçues via le socket
    boost::asio::streambuf stream_buf;
    boost::asio::read(socket, stream_buf);
    std::string received_data = boost::asio::buffer_cast<const char*>(stream_buf.data(), stream_buf.size());

    // Afficher les résultats
    std::cout << "Received from server: " << received_data << std::endl;

    return 0;
}
```

