        asio::ip::tcp::acceptor acceptor(io_context, asio::ip::tcp::endpoint(asio::ip::tcp::v4(), 1234));

        for (;;) {
            // Attendre une nouvelle connexion
            asio::ip::tcp::socket socket(io_context);
            acceptor.accept(socket);

            // Envoyer un message statique
