function ComponentA() {
  const [showComponentB, setShowComponentB] = useState(false);

  useEffect(() => {
    // Some code that updates showComponentB to true or false
  }, []);

  if (showComponentB) {
    return <ComponentB />;
  } else {
    return null;
  }
}

function ComponentB(props) {
  useEffect(() => {
    return () => {
      console.log('ComponentB is being destroyed!');
      // Libérer des ressources, si nécessaire
      props.onDestruction();
      // ForceUpdate pour forcer la mise à jour de l'état du composant parent
      props.parent.forceUpdate();
    };
  }, []);

  // ... Le reste du code du composant ComponentB
}

// Pour les fonctions React, utilisez les prop-types pour spécifier le parent qui dispose de la méthode forceUpdate(), ainsi que les props custom que vous souhaiteriez transmettre à la fonction de destruction.
ComponentB.propTypes = {
  parent: PropTypes.object.isRequired,
  onDestruction: PropTypes.func
};

export default ComponentA;
